(()=>{'use strict';const S=window.AtelierStudio;let tab='cards',audio=null,view;const scenes=[['none','Aucun'],['rain','Pluie'],['forest','Forêt'],['water','Eau'],['fire','Feu']];
 S.playScene=async scene=>{if(audio){audio.pause();audio=null}if(!scene||scene==='none')return;const setting=S.of('preferences').find(o=>o.id==='ambience-'+scene);if(!setting?.data.asset_id){S.error(Error('Importe ton son « '+(scenes.find(s=>s[0]===scene)?.[1]||scene)+' » dans Mes outils → Ambiances.'));return}audio=new Audio(await S.assetURL(setting.data.asset_id));audio.loop=true;audio.volume=.25;await audio.play()};
 S.cardReader=card=>{let current=card,back=false;openModal('<div id="studioCardReaderHost"></div>');const host=document.getElementById('studioCardReaderHost');const reader=S.node('article','studio-card-reader'),toolbar=S.node('div','studio-toolbar');reader.tabIndex=0;reader.style.background='#eee8d5';reader.style.color='#2a402e';host.append(reader,toolbar);function draw(){reader.textContent=back?current.data.back||current.data.prompt||'':current.data.front||current.data.title;if(current.data.background_asset)S.assetURL(current.data.background_asset).then(url=>{reader.style.backgroundImage='linear-gradient(#eee8d5'+Math.round((1-Number(current.data.opacity??.3))*255).toString(16).padStart(2,'0')+',#eee8d5aa),url("'+url+'")'}).catch(S.error)}const flip=()=>{back=!back;draw()};const next=step=>{const all=S.of('card'),i=all.findIndex(o=>o.id===current.id);current=all[(i+step+all.length)%all.length]||current;back=false;draw()};toolbar.append(S.button('‹ Carte',()=>next(-1)),S.button('Retourner',flip),S.button('Carte ›',()=>next(1)),S.button('Répondre',()=>{S.form('Ma réponse',[{key:'answer',label:current.data.prompt||'Ma réponse',type:'textarea'}],{id:current.id,answer:current.data.answer||''},async v=>{if(current.kind)current=await S.save({...current,data:{...current.data,answer:v.answer}});else{current.data.answer=v.answer;localStorage.setItem('studio-local-card-answer:'+current.data.front,v.answer)}})}),S.button('Fermer',()=>{S.playScene('none');closeModal()}));let x;reader.onpointerdown=e=>x=e.clientX;reader.onpointerup=e=>{if(x==null)return;const dx=e.clientX-x;if(Math.abs(dx)>60)next(dx<0?1:-1);else flip();x=null};reader.onkeydown=e=>{if(e.key==='ArrowRight')next(1);if(e.key==='ArrowLeft')next(-1);if(e.key==='Enter'||e.key===' ')flip()};draw();};

})();
